CREATE OR REPLACE FUNCTION export_private.profile_hooks_valid_v1()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare r record;p pg_proc;begin
 for r in select key,value#>>'{}' digest from jsonb_each('{"notification_private.hash(jsonb)":"56d037a72a2869b2a5a9fc529d7f4f65","notification_private.uuid(jsonb)":"807ab1cc00b54bb5318e4e9166c80d1c","profile_data_private.sources_v1()":"5811d9fda1b78cf6916dff6375347e74","notification_private.canonical(jsonb)":"d64328eb0b38e8af0414c32ed690af90","export_private.profile_source_v1(uuid)":"9c8e2536d5d16a026303f4de1441962a","profile_data_private.inventory_v1(uuid)":"b7d92626b8d2076e4f8285e06e8e48ca","export_private.lock_job_v1(uuid,boolean)":"39974e02b9e5bb9f732e902f46e25dfb","notification_private.exact(jsonb,text[])":"0efb90311270494f2df2ebdaf81a3bc1","public.privacy_core_export_v1(text,jsonb)":"58745517aac9fb29740c3dba6893887a","export_private.core_profile_page_v1(jsonb)":"97bc38733014d3c39a5b9d1fe2a3cb14","export_private.profile_ids_v1(jsonb,integer)":"d868816850af0affc3233f6cd681f9b5","export_private.profile_copies_valid_v1(jsonb)":"5d95d5e293a56216314dbc8935adb2ae","export_private.profile_summary_valid_v1(jsonb)":"731b398085cb2f6de2da8d16dad50060","export_private.valid_modules_v1(jsonb,integer)":"a012fc7607e819051c4b83867b4e4ad4","export_private.profile_integer_v1(jsonb,bigint)":"114575989f2ce7b0eb7b350514f2f86d","export_private.profile_natural_v1(jsonb,bigint)":"4f91a39b4198c9f7b9b8778bf1f95561","export_private.profile_row_valid_v1(jsonb,uuid)":"847b8f7f39004426cc4668734e02be58","export_private.profile_conflicts_valid_v1(jsonb)":"34875bab4b6c05c2f261ee53e21c0716","export_private.profile_provenance_immutable_v1()":"bc691ef7f0df72ff9d3bbf338fb65401","export_private.profile_managed_copy_v1(uuid,uuid)":"ac28e7dfeda5a9f101a55c887c946019","export_private.profile_normalize_integers_v1(jsonb)":"2b4badb49c04be45044bc69b92bbc194","profile_data_private.profile_v1(public.user_profiles)":"3e1055c61a20408bee0e2ec59b876b13","export_private.profile_operation_valid_v1(jsonb,uuid,bigint)":"9e450fb166ff6a84f64fda59811c49a6","export_private.profile_source_current_v1(export_private.core_jobs_v1)":"f6bebdc133d93fd56b8d613b9e931c1d","export_private.live_lease_v1(export_private.core_jobs_v1,uuid,integer)":"10646bcc81751f81d1d0eaa994e26f43","profile_data_private.operation_row_v1(profile_data_private.operations_v1)":"442d85cb715f67c9376228407e0b2c8c","export_private.profile_decision_valid_v1(jsonb,text,bigint,bigint,bigint,integer)":"702505b2b62ef7945c5bf9962a4aaf25","profile_data_private.summary_v1(public.user_profiles,profile_data_private.watermarks_v1)":"b3f86bebba4fd3596933639c1c9cdebc","export_private.profile_commit_qualifies_v1(export_private.core_jobs_v1,jsonb,uuid,integer)":"73f01147e5cf00a70f2bf4d02b0527ca","export_private.record_profile_provenance_v1(export_private.core_jobs_v1,timestamp with time zone)":"9ab3e8032407f9e566ccd6156a2cfdfe"}'::jsonb) loop
  if to_regprocedure(r.key) is null then return false;end if;
  select * into p from pg_proc where oid=r.key::regprocedure;
  if md5(pg_get_functiondef(p.oid)) is distinct from r.digest then return false;end if;
 end loop;
 return true;
end$function$
